import { DiagramKey } from '../shared/diagrams';

/**
 * The interview bank. Two kinds of questions:
 *  - mcq  : one correct choice, auto-graded.
 *  - open : you answer out loud / in the textarea; key points are auto-detected by keywords,
 *           then YOU confirm each one (self-grading, like a real debrief).
 * Explanations are HTML (rendered with [innerHTML]) and may reference a diagram + a lesson.
 */
export type Topic = 'angular' | 'dotnet' | 'auth' | 'architecture';
export type Level = 1 | 2 | 3;

interface Base {
  id: string; topic: Topic; level: Level; question: string;
  explanation?: string;          // MCQ: always set. Open: the `model` answer plays that role.
  diagram?: DiagramKey; lesson?: string;
}
export interface McqQuestion extends Base { type: 'mcq'; choices: string[]; answer: number; }
export interface KeyPoint { text: string; keywords: string[]; }
export interface OpenQuestion extends Base { type: 'open'; keyPoints: KeyPoint[]; model: string; }
export type Question = McqQuestion | OpenQuestion;

export const TOPICS: Record<Topic, { label: string; color: string }> = {
  angular: { label: 'Angular', color: 'var(--angular)' },
  dotnet: { label: '.NET', color: 'var(--dotnet)' },
  auth: { label: 'Auth & sécurité', color: 'var(--auth)' },
  architecture: { label: 'Architecture', color: 'var(--brand-2)' },
};
